/* ---- the one resolver every reader goes through ---------------------------
   The four checks are hal/intro_kuppa_dispatch.cpp's plus the unhosted row:
   an index the ROM would have read off the end of the table, a mount holding
   bytes that are not the ROM's, a record that is not a plain {function, 0}
   pair, and a cell with no matched TU. Each is a finding rather than something
   to execute, so each aborts by name. */
/* SM64DS_CUTSCENE_STATES=1: a per-cell census, printed once at exit. Inert
   unset (one getenv, cached), and it is a MEASUREMENT rather than an
   assertion -- without it a table nothing dispatches and a table that runs
   every frame produce exactly the same silence, which are opposite findings.
   The counter is keyed by the array's own address so a cell that two runs
   disagree about is nameable, and the report prints the ROM address of every
   entered cell so it can be joined against port/slice_gate219.txt. */
static struct { unsigned arr; unsigned idx; unsigned long n; } g_st_seen[128];
static int g_st_nseen;
static int g_st_on = -1;

static void st_report(void)
{
    std::printf("  [cutscene-states] %d distinct cells entered\n", g_st_nseen);
    for (int i = 0; i < g_st_nseen; ++i)
        std::printf("  [cutscene-states] %08x[%u] x%lu\n", g_st_seen[i].arr,
                    g_st_seen[i].idx, g_st_seen[i].n);
    std::fflush(stdout);
}

static void st_note(const char *arr, unsigned idx)
{
    if (g_st_on < 0) {
        g_st_on = std::getenv("SM64DS_CUTSCENE_STATES") != 0;
        if (g_st_on) std::atexit(st_report);
    }
    if (!g_st_on) return;
    /* the array name is "data_ov002_<8 hex>"; its address is the tail */
    unsigned a = (unsigned)std::strtoul(arr + 11, 0, 16);
    for (int i = 0; i < g_st_nseen; ++i)
        if (g_st_seen[i].arr == a && g_st_seen[i].idx == idx) {
            ++g_st_seen[i].n;
            return;
        }
    if (g_st_nseen < (int)(sizeof g_st_seen / sizeof g_st_seen[0])) {
        g_st_seen[g_st_nseen].arr = a;
        g_st_seen[g_st_nseen].idx = idx;
        g_st_seen[g_st_nseen].n = 1;
        ++g_st_nseen;
    }
}

static void *st_resolve(const char *arr, const PortStateCell *cells,
                        const PortStateRow *rows, unsigned n, unsigned idx)
{
    if (idx >= n) {
        std::fprintf(stderr, "FATAL: %s index %u is off the end of a %u-cell "
                     "table\n", arr, idx, n);
        std::abort();
    }
    if (cells[idx].fn != rows[idx].rom) {
        std::fprintf(stderr, "FATAL: %s[%u]: the mount holds %08x, the ROM's "
                     "own record says %08x -- WRONG BYTES\n", arr, idx,
                     cells[idx].fn, rows[idx].rom);
        std::abort();
    }
    if (cells[idx].delta != 0) {
        std::fprintf(stderr, "FATAL: %s[%u] is not a plain pointer-to-member "
                     "(this-adjustment %d)\n", arr, idx, cells[idx].delta);
        std::abort();
    }
    st_note(arr, idx);
    if (rows[idx].host == 0) {
        std::fprintf(stderr, "UNHOSTED: %s[%u] is func_ov002_%08x, which has no "
                     "matched TU anywhere in src/ -- see the header of "
                     "hal/cutscene_states_link100.cpp\n", arr, idx,
                     rows[idx].rom);
        std::abort();
    }
    return rows[idx].host;
}

typedef void (*PortState1)(void *self, int idx);
typedef void (*PortState0)(void *self);

#define ST_CALL1(A, IDX, SELF, ARG)                                           \
    ((PortState1)st_resolve("data_ov002_" #A, data_ov002_##A, g_st_##A,        \
                            (unsigned)(sizeof g_st_##A / sizeof g_st_##A[0]),  \
                            (unsigned)(IDX)))((SELF), (ARG))
#define ST_CALL0(A, IDX, SELF)                                                \
    ((PortState0)st_resolve("data_ov002_" #A, data_ov002_##A, g_st_##A,        \
                            (unsigned)(sizeof g_st_##A / sizeof g_st_##A[0]),  \
                            (unsigned)(IDX)))((SELF))

